-- BP-41 (Poker hỗn loạn round three, spec 2026-10-28 §4.4): the three title counters on `player_stats` — times a player
-- became the Thần Bài, became a Bán Thần, and won a hand against a human Thần — which drive the achievements
-- `chaos_god`, `chaos_demigod` and `chaos_godslayer`.
-- Generated by `pnpm --filter @bp/normal-server db:generate --name chaos_titles`, then guarded with IF NOT EXISTS in
-- `0007_chaos.sql`'s style, so a second run is a no-op. Additive: three integer columns, 0 for every existing player.
ALTER TABLE "player_stats" ADD COLUMN IF NOT EXISTS "chaos_ascensions" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "player_stats" ADD COLUMN IF NOT EXISTS "chaos_demigods" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "player_stats" ADD COLUMN IF NOT EXISTS "chaos_gods_slain" integer DEFAULT 0 NOT NULL;
